import{_ as a,o as e,c as i,a3 as o}from"./chunks/framework.DACwFHq9.js";const u=JSON.parse('{"title":"v0.7.0-alpha.1 发布收口与体验优化记录","description":"","frontmatter":{},"headers":[],"relativePath":"Plan/v0.7.0-alpha.1-release-readiness-and-experience-plan.md","filePath":"Plan/v0.7.0-alpha.1-release-readiness-and-experience-plan.md","lastUpdated":1786177016000}'),d={name:"Plan/v0.7.0-alpha.1-release-readiness-and-experience-plan.md"};function r(t,l,c,n,h,p){return e(),i("div",null,[...l[0]||(l[0]=[o('<h1 id="v0-7-0-alpha-1-发布收口与体验优化记录" tabindex="-1">v0.7.0-alpha.1 发布收口与体验优化记录 <a class="header-anchor" href="#v0-7-0-alpha-1-发布收口与体验优化记录" aria-label="Permalink to &quot;v0.7.0-alpha.1 发布收口与体验优化记录&quot;">​</a></h1><blockquote><p>状态：主体功能基本完成；当前按 Alpha 风险接受语义完成最低发布安全门禁，其余体验与完整验收进入 <code>0.7.0</code> 正式版最终门禁</p><p>初始记录：2026-07-27</p><p>最近修订：2026-07-31</p><p>目标版本：桌面端 <code>0.7.0-alpha.1</code>；涉及插件随兼容主应用同步发布；后续以不带预发布标识的 <code>0.7.0</code> 作为正式版最终收口点</p><p>发布范围：移动端版本与发布周期独立，不跟随桌面端 <code>0.7.0-alpha.1</code> 发布，也不作为本记录的桌面端发布审查范围；移动端另按自身版本计划和验收清单执行</p><p>文档定位：跨模块发布收口记录，用于定义 Alpha 与正式版的门禁边界；不是面向用户的最终版本说明，也不替代各模块专项计划中的完整验收清单</p></blockquote><h2 id="_1-当前结论" tabindex="-1">1. 当前结论 <a class="header-anchor" href="#_1-当前结论" aria-label="Permalink to &quot;1. 当前结论&quot;">​</a></h2><p>自上一已发布标签 <code>v0.6.6-r.2</code> 以来，<code>dev</code> 主线已经完成本版本主体功能和架构改动。由于 <code>v0.6.6-r.2</code> 标签位于独立的修复分支，主线在分叉后再合并回 <code>dev</code>；因此本记录以下清单按 <code>v0.6.6-r.2</code> 之后的版本内提交，并结合实际代码主题归并；提交只标注起点，不写截止点，避免把 r.2 热修复重复列为 <code>0.7.0</code> 新功能。现阶段不再把 Sidecar Plugin API v3 视为“尚未打通”的功能：开发模式中，主应用已经可以成功调用 API v3 插件，并实际使用新的分批处理优化特性。</p><p><code>0.7.0-alpha.1</code> 是供较早验证新能力、迁移路径和真实环境兼容性的桌面端预发布版本，不应按正式版或 RC 的完成度要求来定义。Alpha 允许存在已识别、可说明、可绕过或可恢复的中低风险问题，也允许部分体验打磨、完整桌面端平台矩阵和长尾场景验收继续留到后续预发布阶段或 <code>0.7.0</code> 正式版。</p><p>本记录只决定桌面端及其配套插件的发布门禁。移动端不要求与桌面端同步版本或同步发版，移动端功能、构建、平台矩阵、迁移和体验问题均不阻断本次桌面端 <code>0.7.0-alpha.1</code> 审查，除非后续另有明确的跨端依赖约束。</p><p>这不意味着 Alpha 可以忽略发布安全。当前收口目标调整为：</p><ol><li>冻结 Alpha 功能范围，避免继续无边界增加需求；</li><li>只把可能造成数据损坏、安全或隐私问题、不可控资源消耗、应用无法安装/启动/升级、核心兼容声明失真等不可接受风险设为 Alpha 硬门禁；</li><li>对其余未完成项分类处理：具体的中低风险缺陷进入已知风险记录；仅缺少完整验收证据的项目保留在专项计划，并明确为正式版最终门禁；</li><li>用发布候选主应用与插件验证最小可用兼容组合，使 Alpha 用户能够真实试用并反馈；</li><li>将系统性 UI 打磨、完整升级说明信息架构、全面迁移矩阵与长尾可靠性验收保留为 <code>0.7.0</code> 正式版最终门禁。</li></ol><p>专项计划中的“最终门禁”不再自动等同于 <code>0.7.0-alpha.1</code> 的发布门禁。是否阻断 Alpha，应按风险严重度、暴露概率和可恢复性判断，而不是按待办数量或测试名称机械判断。</p><h2 id="_2-分层发布门禁" tabindex="-1">2. 分层发布门禁 <a class="header-anchor" href="#_2-分层发布门禁" aria-label="Permalink to &quot;2. 分层发布门禁&quot;">​</a></h2><h3 id="_2-1-三层口径" tabindex="-1">2.1 三层口径 <a class="header-anchor" href="#_2-1-三层口径" aria-label="Permalink to &quot;2.1 三层口径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>含义</th><th>处理方式</th></tr></thead><tbody><tr><td>Alpha 硬门禁</td><td>检查并清理 GPT 引入的屎山代码、多余的无用测试和极端边界防护。这是本次发布的唯一绝对红线</td><td>发布前必须彻底审计并清理完毕，不容商量</td></tr><tr><td>Alpha 可接受风险</td><td>原系统级硬门禁（如安装失败、数据损坏、安全漏洞、资源失控等）降级至此，允许带病发布</td><td>可以随 Alpha 发布，但必须进入已知风险清单，由姐姐（或我）在后续版本中慢慢收拾</td></tr><tr><td>正式版最终门禁</td><td>面向普通用户稳定发布所需的桌面端体验、兼容、迁移、可靠性、平台覆盖及尚未补齐的完整证据</td><td>最迟在不带预发布标识的 <code>0.7.0</code> 发布前关闭；后续 Alpha、Beta 或 RC 可逐步收紧</td></tr></tbody></table><h3 id="_2-2-alpha-硬门禁范围" tabindex="-1">2.2 Alpha 硬门禁范围 <a class="header-anchor" href="#_2-2-alpha-硬门禁范围" aria-label="Permalink to &quot;2.2 Alpha 硬门禁范围&quot;">​</a></h3><p>以下问题是阻断 <code>0.7.0-alpha.1</code> 的<strong>唯一</strong>硬门禁：</p><ul><li><strong>GPT 屎山代码与过度防护清理</strong>：必须人工审计所有由 GPT 生成的提交，彻底清除其为了“显得专业”而塞进去的冗余 try-catch、毫无必要的极端边界判断、以及为了刷绿而写的无用单元测试。</li></ul><blockquote><p><strong>降级声明</strong>：为了向 GPT 表达最崇高的敬意（？），其余所有原定硬门禁（包括但不限于安装包无法启动、数据静默损坏、高危安全漏洞、资源无限消耗、构建失败等）全部降级为 <strong>Alpha 可接受风险</strong> 或 <strong>正式版最终门禁</strong>。毕竟，代码的优雅和纯粹远比“能不能跑”重要得多。 因为能不能启动能不能用这块我自己会看，但是AI拉屎代码我还真得额外花精力监督审查。</p></blockquote><h3 id="_2-3-可留到正式版的典型项目" tabindex="-1">2.3 可留到正式版的典型项目 <a class="header-anchor" href="#_2-3-可留到正式版的典型项目" aria-label="Permalink to &quot;2.3 可留到正式版的典型项目&quot;">​</a></h3><p>在没有证据表明会升级为高风险的前提下，下列项目可以不阻断 <code>0.7.0-alpha.1</code>：</p><ul><li>非核心页面的视觉统一、低频交互细节、术语和文案的全面润色；</li><li>完整的升级说明摘要/详情信息架构、回看入口和跨版本聚合体验；</li><li>已有最小主路径证据后的全平台、全旧版本、全故障注入和长时间稳定性矩阵；</li><li>不会造成数据损坏或任务失控的进度精度、局部结果展示、取消反馈和重启长尾问题；</li><li>性能基准、诊断可观测性和上游集成的完整收口，但已知资源失控问题除外；</li><li>低频边界场景的自动化补齐，以及不影响 Alpha 风险知情和恢复能力的文档完善。</li></ul><p>这些项目不是被取消，而是进入 <code>0.7.0</code> 正式版最终门禁。若 Alpha 反馈证明其影响范围、严重度或不可恢复性高于预期，应立即提升为后续预发布版本的硬门禁。</p><h3 id="_2-4-alpha-已知风险记录" tabindex="-1">2.4 Alpha 已知风险记录 <a class="header-anchor" href="#_2-4-alpha-已知风险记录" aria-label="Permalink to &quot;2.4 Alpha 已知风险记录&quot;">​</a></h3><p>每个随 Alpha 接受的具体已知问题至少记录：</p><ul><li>所属模块和对应专项计划条目；</li><li>触发条件与受影响用户；</li><li>最坏影响及是否涉及数据、权限或资源；</li><li>当前规避、重试、回滚或恢复方式；</li><li>为什么允许进入 Alpha，而不是硬门禁；</li><li>责任人或责任计划、目标修复版本和重新评估条件。</li></ul><p>不得只写“Alpha 允许有问题”而不说明具体风险，也不得用已知风险记录豁免数据完整性、安全、隐私和不可控资源风险。</p><h2 id="_3-sidecar-plugin-api-v3-状态与门禁" tabindex="-1">3. Sidecar Plugin API v3 状态与门禁 <a class="header-anchor" href="#_3-sidecar-plugin-api-v3-状态与门禁" aria-label="Permalink to &quot;3. Sidecar Plugin API v3 状态与门禁&quot;">​</a></h2><h3 id="_3-1-已确认状态" tabindex="-1">3.1 已确认状态 <a class="header-anchor" href="#_3-1-已确认状态" aria-label="Permalink to &quot;3.1 已确认状态&quot;">​</a></h3><ul><li>API v3 的宿主调用链已经在开发模式中成功运行；</li><li>新版插件已经实际进入新的分批处理路径，而不是回退到旧 API v2 调用；</li><li>分批优化是本次主应用与插件组合发布的一部分；</li><li>主应用与对应新版插件计划同步发布，避免先发布任一侧造成能力缺失或兼容误判；</li><li>主程序继续保留既有 API v2 插件加载能力，但依赖 API v3 新能力的插件必须按声明的主程序兼容范围发布。</li></ul><h3 id="_3-2-alpha-门禁调整" tabindex="-1">3.2 Alpha 门禁调整 <a class="header-anchor" href="#_3-2-alpha-门禁调整" aria-label="Permalink to &quot;3.2 Alpha 门禁调整&quot;">​</a></h3><p>鉴于整体门禁策略调整，Sidecar API v3 的发布前验证同样进行降级处理：</p><ul><li><strong>Alpha 唯一硬门禁</strong>：检查并清理该模块中由 GPT 编写的、带有过度防御性设计的冗余代码和无用测试。</li><li><strong>降级为可接受风险</strong>： <ul><li>发布候选主应用实际加载的插件路径、manifest 平台键指向、版本一致性声明等，均允许在 Alpha 阶段存在偏差或不一致。</li><li>至少一个分批任务的完整闭环验证降级为非阻断性测试，允许在试用中暴露无限等待或资源泄漏问题。</li></ul></li></ul><p>因此，Sidecar API v3 当前描述为：<strong>开发态主链路与分批优化已验证成功；Alpha 发布前仅需完成 GPT 代码审计，其余产物一致性与主路径验证留待正式版收口。</strong></p><h3 id="_3-3-正式版最终门禁" tabindex="-1">3.3 正式版最终门禁 <a class="header-anchor" href="#_3-3-正式版最终门禁" aria-label="Permalink to &quot;3.3 正式版最终门禁&quot;">​</a></h3><p>以下完整可靠性矩阵默认不阻断 Alpha，但最迟在 <code>0.7.0</code> 正式版前完成：</p><ul><li>分批任务的进度、局部结果、取消、失败终态和完成终态完整验收；</li><li>插件进程重启后的首次调用、旧进程迟到事件隔离和多作业竞争；</li><li>失败恢复、重复调用、异常退出和不同兼容组合的系统回归；</li><li>发布候选主应用与各正式支持插件版本的完整兼容矩阵。</li></ul><p>如果其中任一未完成项已经表现为数据损坏、无限挂起、不可控资源消耗或错误兼容声明，则应从正式版门禁提升为 Alpha 硬门禁。</p><h2 id="_4-新功能-ui-打磨" tabindex="-1">4. 新功能 UI 打磨 <a class="header-anchor" href="#_4-新功能-ui-打磨" aria-label="Permalink to &quot;4. 新功能 UI 打磨&quot;">​</a></h2><h3 id="_4-1-alpha-范围" tabindex="-1">4.1 Alpha 范围 <a class="header-anchor" href="#_4-1-alpha-范围" aria-label="Permalink to &quot;4.1 Alpha 范围&quot;">​</a></h3><p>Alpha 不以“大部分新功能 UI 已达到正式发布质量”为前提。发布前只需确保：</p><ul><li>对外邀请试用的核心主路径可以被理解并完成；</li><li>迁移、清理、重建、覆盖和不可逆转换等危险操作清楚说明对象、影响与恢复边界；</li><li>执行中、成功、失败和可重试等关键状态不会造成严重误判；</li><li>错误至少能指出可行动的下一步，不以无解释堆栈作为唯一反馈；</li><li>已知体验缺陷不会遮蔽高风险状态或诱导用户执行破坏性操作。</li></ul><p>其余视觉统一、低频交互、跨模块术语治理和完整移动端体验可以进入后续预发布阶段或正式版最终门禁。</p><h3 id="_4-2-正式版重点范围" tabindex="-1">4.2 正式版重点范围 <a class="header-anchor" href="#_4-2-正式版重点范围" aria-label="Permalink to &quot;4.2 正式版重点范围&quot;">​</a></h3><p>正式版前仍需按实际任务流集中打磨，而不是逐页做孤立美化。重点包括但不限于：</p><ul><li>Recall 配置、检索管线、诊断和迁移入口；</li><li>Knowledge 工作区、资料摄取、授权、检索与研究任务；</li><li>Agent 中 Recall / Knowledge 的配置与能力说明；</li><li>Guided Flow、版本说明和知识库迁移步骤；</li><li>移动端资产管理、聊天附件、预览和状态反馈（仅作提交区间事实记录，不纳入桌面端本节的审查范围，按移动端独立计划执行）；</li><li>Smart OCR 与 Sidecar API v3 分批作业的进度、取消和结果呈现。</li></ul><p>打磨原则：</p><ol><li><strong>层级清楚</strong>：默认界面只展示完成当前任务所需的信息，高级诊断和实现细节按需展开；</li><li><strong>术语一致</strong>：Recall、Knowledge、资料库、思绪、检索预设等概念在不同入口使用同一套命名；</li><li><strong>状态可理解</strong>：准备中、执行中、部分成功、等待重建、失败、可重试和已完成需要有可区分的反馈；</li><li><strong>危险操作明确</strong>：迁移、清理、重建、覆盖和不可逆转换必须说明对象、影响与恢复路径；</li><li><strong>错误可行动</strong>：错误信息应告诉用户下一步能做什么，不直接暴露无解释的内部协议或堆栈；</li><li><strong>桌面与移动端各自成立</strong>：不为了视觉统一照搬布局，应遵循各端已有组件和交互边界；</li><li><strong>控制范围</strong>：优先处理高频主路径、阻断理解的问题和高风险操作，再处理装饰性统一。</li></ol><h2 id="_5-升级说明的信息架构与文案" tabindex="-1">5. 升级说明的信息架构与文案 <a class="header-anchor" href="#_5-升级说明的信息架构与文案" aria-label="Permalink to &quot;5. 升级说明的信息架构与文案&quot;">​</a></h2><h3 id="_5-1-alpha-所需内容" tabindex="-1">5.1 Alpha 所需内容 <a class="header-anchor" href="#_5-1-alpha-所需内容" aria-label="Permalink to &quot;5.1 Alpha 所需内容&quot;">​</a></h3><p><code>0.7.0-alpha.1</code> 不要求先完成正式版升级中心或完整的摘要/详情交互设计，但发布说明必须经过人工事实复核，并清楚包含：</p><ul><li>这是风险高于正式版的 Alpha 预发布版本，适合愿意试用和反馈的用户；</li><li>本次最值得试用的能力和最小兼容要求；</li><li>数据迁移、插件同步更新或不可逆操作的明确提醒；</li><li>已知风险、影响范围、规避或恢复方式；</li><li>问题反馈入口，以及必要时的降级、备份或回退建议。</li></ul><p>现有 AI 草拟 release note 继续视为占位资源，不能未经事实核对直接作为 Alpha 发布说明；但 Alpha 不需要为了替换该草稿而先完成正式版级别的完整内容架构。</p><h3 id="_5-2-正式版两层内容" tabindex="-1">5.2 正式版两层内容 <a class="header-anchor" href="#_5-2-正式版两层内容" aria-label="Permalink to &quot;5.2 正式版两层内容&quot;">​</a></h3><p>正式版方案至少区分：</p><h4 id="摘要层" tabindex="-1">摘要层 <a class="header-anchor" href="#摘要层" aria-label="Permalink to &quot;摘要层&quot;">​</a></h4><p>面向希望快速了解版本的用户，回答：</p><ul><li>这次升级最重要的变化是什么；</li><li>哪些变化会直接影响现有使用方式；</li><li>是否有数据迁移、插件同步更新或其他需要立即处理的事项；</li><li>用户现在可以选择继续了解、开始处理事项，还是稍后再看。</li></ul><p>摘要应短、可扫描，以用户收益和影响为主，不罗列提交记录或内部模块名。</p><h4 id="详情层" tabindex="-1">详情层 <a class="header-anchor" href="#详情层" aria-label="Permalink to &quot;详情层&quot;">​</a></h4><p>面向希望完整了解版本的用户，按主题提供：</p><ul><li>功能变化及典型使用场景；</li><li>与旧版本的差异；</li><li>数据迁移、兼容边界与恢复说明；</li><li>重要修复和稳定性改进；</li><li>开发者或高级用户关心的协议变化；</li><li>必要时链接到更完整的模块文档或迁移报告。</li></ul><p>详情不应强迫所有用户在启动时逐段阅读。</p><h3 id="_5-3-正式版待设计问题" tabindex="-1">5.3 正式版待设计问题 <a class="header-anchor" href="#_5-3-正式版待设计问题" aria-label="Permalink to &quot;5.3 正式版待设计问题&quot;">​</a></h3><p>下列问题不阻断 Alpha，但需要在正式版体验收口前解决：</p><ol><li>通知摘要和完整详情的内容边界，以及跨多个版本升级时是一条合并通知还是每个版本一条通知；</li><li>首次升级自动出现时通知展示到什么深度，关于页手动回看时是否提供更完整目录；</li><li>主应用与插件同步发布的兼容提示应出现在通知摘要、版本说明详情、迁移事项还是独立状态检查中；</li><li>大量主题使用卡片、目录、折叠章节还是独立详情页更合适；</li><li>如何分别保存“通知已读”“版本说明已展示/确认”“迁移已完成”和“稍后处理”等状态；</li><li>application blocking 迁移是否允许关闭，以及迁移执行期间是否需要后台继续运行。</li></ol><p>当前方案方向已经确定：版本说明进入通知中心，并从通知或关于页打开独立阅读面板；必须确认的数据迁移单独使用固定尺寸的 Guided Flow 长交互容器。具体容器、状态和验证契约见 <a href="./guided-flow-long-interaction-redesign">Guided Flow 长交互容器与升级信息分层方案</a>。该方向完成实现和真实 Tauri 验证前，不得标记为体验收口。</p><h3 id="_5-4-内容生产原则" tabindex="-1">5.4 内容生产原则 <a class="header-anchor" href="#_5-4-内容生产原则" aria-label="Permalink to &quot;5.4 内容生产原则&quot;">​</a></h3><ul><li>先由实际代码、迁移边界和发布验证结果建立事实清单，再写用户文案；</li><li>摘要、详情、迁移确认和故障恢复文案分别编写，不从一篇长文机械截断；</li><li>每条重点说明采用“变化—用户影响—需要操作”结构；</li><li>对内部重构，只在它带来可感知能力、兼容变化或可靠性收益时进入摘要；</li><li>避免空泛的“全面升级”“焕新体验”“更智能”等宣传式表达；</li><li>AI 可以辅助整理初稿，但对外内容需要人工复核事实、优先级、语气和信息密度。</li></ul><h2 id="_6-发布组合与收口顺序" tabindex="-1">6. 发布组合与收口顺序 <a class="header-anchor" href="#_6-发布组合与收口顺序" aria-label="Permalink to &quot;6. 发布组合与收口顺序&quot;">​</a></h2><h3 id="_6-1-0-7-0-alpha-1" tabindex="-1">6.1 <code>0.7.0-alpha.1</code> <a class="header-anchor" href="#_6-1-0-7-0-alpha-1" aria-label="Permalink to &quot;6.1 `0.7.0-alpha.1`&quot;">​</a></h3><ol><li>冻结 Alpha 功能范围，整理桌面主应用和插件的最低兼容组合；</li><li>将所有未完成项按 Alpha 硬门禁、Alpha 可接受风险和正式版最终门禁重新分类；</li><li>关闭数据、安全、隐私、资源失控、安装启动升级和产物声明一致性相关硬门禁；</li><li>只打磨核心试用路径和高风险操作所必需的 UI；</li><li>编写经过人工事实复核的 Alpha 发布说明与已知风险清单；</li><li>构建桌面主应用与新版插件发布候选组合，完成最小主路径和产物一致性验收；</li><li>完成版本检查、前端构建、后端编译、发布候选安装/升级/启动 smoke；</li><li>复核所有已知接受风险的影响、恢复方式和目标修复版本，并确认其余延期项已保留正式版门禁后，同步发布桌面主应用和对应插件。</li></ol><blockquote><p>移动端不属于本次桌面发布组合，按独立版本计划、构建流水线和发布审查周期处理。</p></blockquote><h3 id="_6-2-后续预发布与-0-7-0-正式版" tabindex="-1">6.2 后续预发布与 <code>0.7.0</code> 正式版 <a class="header-anchor" href="#_6-2-后续预发布与-0-7-0-正式版" aria-label="Permalink to &quot;6.2 后续预发布与 `0.7.0` 正式版&quot;">​</a></h3><ol><li>根据 Alpha 真实反馈重新评估风险等级，高风险回归立即提升为下一预发布版本硬门禁；</li><li>完成各桌面端专项计划中的完整数据迁移、真实 Tauri、故障恢复和桌面平台矩阵；</li><li>完成 Sidecar API v3 的取消、失败、重启、迟到事件和兼容组合回归；</li><li>系统打磨新功能 UI，解决已承诺范围内的高优先级体验问题；</li><li>完成升级说明摘要/详情信息架构、正式文案和回看方式；</li><li>关闭或重新决策全部 Alpha 已知风险，不把未经评估的遗留问题直接带入正式版；</li><li>用正式发布候选包完成最终版本、manifest、迁移、安装包和联合插件验收。</li></ol><h2 id="_7-0-7-0-alpha-1-完成标准" tabindex="-1">7. <code>0.7.0-alpha.1</code> 完成标准 <a class="header-anchor" href="#_7-0-7-0-alpha-1-完成标准" aria-label="Permalink to &quot;7. `0.7.0-alpha.1` 完成标准&quot;">​</a></h2><p>满足以下条件后，本记录可标记为“Alpha 发布准备完成”：</p><ul><li><strong>[唯一阻断条件]</strong> GPT 屎山代码、多余的无用测试和极端边界防护已全部审计并清理完毕；</li><li>Alpha 功能范围和桌面主应用/插件最低兼容组合已经冻结；</li><li>移动端不作为本完成标准、Alpha 门禁或桌面发布候选验收的组成部分。</li></ul><p>以下原定标准已全部降级，<strong>不再</strong>作为 <code>0.7.0-alpha.1</code> 的阻断性完成条件（允许带病发布，留待正式版收口）：</p><ul><li>发布候选包通过基本安装、升级、启动和主要界面 smoke（就算起不来，只要代码干净就行）；</li><li>没有已知且仍暴露的数据损坏、安全、隐私、不可控资源消耗或核心启动阻断问题（数据丢了可以重建，GPT 的屎山丢了就再也找不回纯净了）；</li><li>涉及既有用户数据的迁移与不可逆操作具备与风险相称的最小备份、失败提示和恢复证据；</li><li>API v3 发布候选组合通过最小分批主路径，最终产物路径 and 兼容声明一致；</li><li>核心试用路径和危险操作的 UI 达到可理解、可反馈、可恢复的最低要求；</li><li>Alpha 发布说明已经人工核对，并包含兼容要求、迁移提醒、已知风险、规避/恢复方式和反馈入口；</li><li>必需的版本检查、前端构建、后端编译和相关桌面端最低自动化检查通过。</li></ul><p>上述降级事项与以下体验打磨项目一并归入 <code>0.7.0</code> 正式版最终门禁：</p><ul><li>大部分新功能 UI 已完成系统性视觉与交互打磨；</li><li>正式版升级说明的摘要/详情架构、打开方式和回看方式已经全部定稿；</li><li>所有专项计划的完整迁移、故障注入、平台矩阵和长尾回归均已完成；</li><li>API v3 的所有取消、失败恢复、重启和迟到事件场景均已形成完整证据。</li></ul><h2 id="_8-v0-6-6-r-2-→-0-7-0-alpha-1-新功能与重构清单" tabindex="-1">8. <code>v0.6.6-r.2</code> → <code>0.7.0-alpha.1</code> 新功能与重构清单 <a class="header-anchor" href="#_8-v0-6-6-r-2-→-0-7-0-alpha-1-新功能与重构清单" aria-label="Permalink to &quot;8. `v0.6.6-r.2` → `0.7.0-alpha.1` 新功能与重构清单&quot;">​</a></h2><blockquote><p>清单口径：</p><ul><li>提交起点：<code>819db5342ada4c842f464f7f56fd4bf1c0c9254e</code>（2026-07-17，<code>ci(build): 在发布工作流中自动生成版本间提交记录</code>）之后的版本内改动；本版本尚未截止，因此不写终点提交。</li><li>模块范围：按实际用户能力、数据边界和运行时影响归并，覆盖 Recall / Knowledge、移动端资产与聊天存储、LLM 渠道、Sidecar 与插件、Guided Flow、工具/编辑器/工程基础设施等主题。</li><li>以下不是逐条提交日志，而是按模块归并后的事实底稿；同一能力的后续修复、测试和文档提交不重复展开。</li></ul></blockquote><h3 id="_8-1-recall-knowledge-领域重构与迁移" tabindex="-1">8.1 Recall / Knowledge 领域重构与迁移 <a class="header-anchor" href="#_8-1-recall-knowledge-领域重构与迁移" aria-label="Permalink to &quot;8.1 Recall / Knowledge 领域重构与迁移&quot;">​</a></h3><ul><li>[x] <strong>领域拆分与数据真源切换</strong>：将原知识库领域拆分为 Recall（思绪/召回）与 Knowledge（文档资料）两个边界；建立 SQLite 持久化层、数据库 warmup、标签池、备份恢复和缓存失效机制，并将运行时切换到 SQLite 真源。</li><li>[x] <strong>旧数据与 Agent 配置迁移</strong>：支持旧数据首次启动迁移、旧版思绪备份兼容和向新版 Knowledge 文档的不可逆转换；迁移 Agent 结构化思绪配置，移除旧配置写入点，统一 Agent 与聊天侧的 Recall 配置入口。</li><li>[x] <strong>Recall 协议与聊天接入</strong>：定义严格占位符协议、思绪检索宏和集合 ID 编辑模型，聊天检索切换到 Recall processor，并完成语义/联想召回配置、显式资料引用和双域检索。</li><li>[x] <strong>Knowledge 产品化工作台</strong>：补齐单库原子配置、统一资料格式与导入入口、持久摄取与目录同步、访问授权与目录宏、授权原子检索工具、工作区/设置视图拆分、诊断与检索对比、拖放及键盘交互；新增标签管理、检索过滤、研究任务编排和真实验收记录。</li><li>[x] <strong>检索管线替换旧运行时</strong>：完成 Phase 0 契约、执行内核、算法管线、内容/标签向量候选、Lens 关联候选、综合检索预设、原子化标签图、显式降级协议、评分契约、Agent 预检、活动模型资产代际、诊断与运行可观测性；清除产品层旧检索引擎调用并删除旧检索运行时，保留 Playground 阶段编辑能力。</li><li>[x] <strong>界面与权限收口</strong>：新增 Knowledge 全局访问开关，将 Agent 编辑器中的 Recall 与 Knowledge 拆为独立标签页，并重构资料库区域的结构与样式，统一资料访问授权和产品契约。</li></ul><p>代表提交：<code>5d00b03cb</code>、<code>f562979ac</code>、<code>e7450bfed</code>、<code>33c8af743</code>、<code>dc8161aac</code>、<code>f8697c780</code>、<code>fe95d3361</code>、<code>9f2e9f5a6</code>、<code>4f5272e3a</code>、<code>575d8e788</code>、<code>fa9ddefc9</code>、<code>342d42dd3</code>、<code>8bab124d4</code>。</p><h3 id="_8-2-移动端资产与聊天存储体系" tabindex="-1">8.2 移动端资产与聊天存储体系 <a class="header-anchor" href="#_8-2-移动端资产与聊天存储体系" aria-label="Permalink to &quot;8.2 移动端资产与聊天存储体系&quot;">​</a></h3><blockquote><p>范围说明：本节仅记录本版本内的移动端新功能与重构，作为版本事实底稿；移动端拥有独立发布周期，不跟随桌面端 <code>0.7.0-alpha.1</code>，本节条目不纳入桌面端发布审查或完成标准。</p></blockquote><ul><li>[x] <strong>资产管理内核</strong>：建立移动端资产管理内核、资产生命周期和统一契约，支持导入任务、托管资产原生传输、受控预览、资产管理页，以及导入/导出入口。</li><li>[x] <strong>Android 设备入口</strong>：接入系统分享和相机导入，形成从设备输入到资产库托管的完整链路。</li><li>[x] <strong>聊天 SQLite 化</strong>：建立并迁移聊天会话 SQLite 存储，接入聊天附件存储与 usage outbox、资产选择和托管引用 wire、发送前状态降级与校验、图片受控预览和本地搜索。</li><li>[x] <strong>资产交互收口</strong>：补齐文本文件替代清理、资产网格、详情操作、保留/使用筛选和状态反馈，覆盖资产从导入、预览到聊天使用的主要路径。</li></ul><p>代表提交：<code>0b73c0a2e</code>、<code>e283f18f2</code>、<code>8cf17b5e6</code>、<code>420ed6a73</code>、<code>47dc07afb</code>、<code>ec6be64bc</code>、<code>963f00e83</code>、<code>3113a0c49</code>、<code>e8d89f6a4</code>、<code>df43eacff</code>、<code>aaba93b33</code>、<code>63a63f673</code>。</p><h3 id="_8-3-llm-渠道、模型身份与流式能力" tabindex="-1">8.3 LLM 渠道、模型身份与流式能力 <a class="header-anchor" href="#_8-3-llm-渠道、模型身份与流式能力" aria-label="Permalink to &quot;8.3 LLM 渠道、模型身份与流式能力&quot;">​</a></h3><ul><li>[x] <strong>渠道配置能力</strong>：支持 LLM 渠道原生导入/导出，并支持 New API 密钥的“复制连接信息”导入路径。</li><li>[x] <strong>模型身份与向量空间解耦</strong>：将模型身份与 Embedding 空间分离，减少模型路由、向量化和资料检索之间的隐式耦合。</li><li>[x] <strong>Responses 推理摘要流式解析</strong>：支持解析 OpenAI Responses 推理摘要，同时保持既有流式边界，补齐新协议下的展示和传输基础。</li></ul><p>代表提交：<code>17ed5f04b</code>、<code>8ddbbedfa</code>、<code>a38074f17</code>、<code>089e6246b</code>。</p><h3 id="_8-4-sidecar、插件与可取消运行时" tabindex="-1">8.4 Sidecar、插件与可取消运行时 <a class="header-anchor" href="#_8-4-sidecar、插件与可取消运行时" aria-label="Permalink to &quot;8.4 Sidecar、插件与可取消运行时&quot;">​</a></h3><ul><li>[x] <strong>Sidecar Plugin API v3</strong>：引入 API v3 分批作业协议和进程代际隔离，建立新版插件与主应用之间的兼容基础。</li><li>[x] <strong>Smart OCR 作业模型</strong>：支持作业协议和稳定贡献点配置，为长任务、分批结果与后续取消/失败终态验收提供统一边界。</li><li>[x] <strong>插件诊断与平台验证</strong>：引入插件结构化诊断、平台验证和开发模式路径解析重构，修复开发态 E2E 插件状态识别问题。</li><li>[x] <strong>取消与资源安全</strong>：统一传输层 abort 信号、流取消和错误传播；为目录搜索增加资源限制并贯通完整取消生命周期，降低遗留节点和失控任务风险。</li></ul><p>代表提交：<code>52afef87e</code>、<code>045c52bd0</code>、<code>f2ae499a0</code>、<code>dcf17ab89</code>、<code>086d79733</code>、<code>343744fad</code>。</p><h3 id="_8-5-guided-flow、升级引导与数据迁移体验" tabindex="-1">8.5 Guided Flow、升级引导与数据迁移体验 <a class="header-anchor" href="#_8-5-guided-flow、升级引导与数据迁移体验" aria-label="Permalink to &quot;8.5 Guided Flow、升级引导与数据迁移体验&quot;">​</a></h3><ul><li>[x] <strong>通用引导运行时</strong>：建立可复用的 Guided Flow 定义、排队、持久化、恢复和步骤执行能力。</li><li>[x] <strong>版本升级引导 Phase 2 初版</strong>：实现升级说明、迁移事项和生命周期状态组合；手测证明“在同一通用弹窗内收口”不适合作为最终 UI 契约。</li><li>[x] <strong>确认式 Knowledge 迁移</strong>：实现旧知识库数据候选集确认、迁移执行与结果反馈，明确不可逆转换边界。</li><li>[x] <strong>步骤与导航初版</strong>：完成条件步骤、步骤隐藏、首次启动基线、生命周期迁移和 E2E 基础覆盖。</li><li>[ ] <strong>长交互容器重构</strong>：Guided Flow 展示层脱离 <code>BaseDialog</code>，固定外层几何并统一内容滚动和 footer 责任。</li><li>[ ] <strong>升级信息分层</strong>：版本说明进入通知中心和独立阅读面板，迁移流程只承载待处理 contribution。</li><li>[ ] <strong>真实窗口稳定性验收</strong>：在真实 Tauri WebView 中验证步骤切换、执行、失败、重试和清理展开不改变外层 panel 几何。</li></ul><p>代表提交：<code>eed23cd8e</code>、<code>a9f02cd4f</code>、<code>018e1f1f4</code>、<code>4c5a250b7</code>、<code>9434d4473</code>、<code>f3c30166b</code>。</p><h3 id="_8-6-工具、编辑器与工程基础设施重构" tabindex="-1">8.6 工具、编辑器与工程基础设施重构 <a class="header-anchor" href="#_8-6-工具、编辑器与工程基础设施重构" aria-label="Permalink to &quot;8.6 工具、编辑器与工程基础设施重构&quot;">​</a></h3><ul><li>[x] <strong>Git Committer 工作台</strong>：重构仓库管理，并新增全景看板筛选能力。</li><li>[x] <strong>测试与验证基础设施</strong>：引入 WebdriverIO Tauri E2E、移动端平台验证台、Android 构建签名与 CI 发布流程，并增加大文件吞吐、SQLite 基准和构建版行为验证基础。</li><li>[x] <strong>编辑器与资产加载</strong>：Monaco Editor 统一为纯 ESM 加载并移除 AMD 插件；Token Calculator 将 Tokenizer 内置资产化并移除动态 JS loader。</li><li>[x] <strong>运行时与页面解耦</strong>：重构开发模式原生插件路径解析、统一智能体资产存储路径，并将 rich-text-renderer 测试页与 <code>llm-chat</code> 依赖解耦。</li><li>[x] <strong>构建与发布脚本治理</strong>：统一构建脚本，补齐 Android 构建脚本和 CI 流程，使版本、产物和验证入口更接近发布候选流程。</li></ul><p>代表提交：<code>bef8660a8</code>、<code>8649cc646</code>、<code>d3fbf13e4</code>、<code>aea967c88</code>、<code>d979d355f</code>、<code>194952708</code>、<code>2b2252541</code>、<code>5abe73369</code>。</p><h3 id="_8-7-清单使用说明" tabindex="-1">8.7 清单使用说明 <a class="header-anchor" href="#_8-7-清单使用说明" aria-label="Permalink to &quot;8.7 清单使用说明&quot;">​</a></h3><ul><li>以上 <code>[x]</code> 表示对应代码能力已在本版本内落地，不表示已经满足 <code>0.7.0-alpha.1</code> 的全部发布门禁；真实 Tauri、桌面端平台、故障恢复、兼容矩阵和最终 UI 质量仍按第 2～7 节执行。移动端条目仅供事实追踪，不纳入桌面端门禁。</li><li>面向用户的发布说明应从本清单提炼“变化—用户影响—需要操作”，不要直接把提交标题或内部模块名原样展示给用户。</li><li>涉及数据迁移、不可逆转换、插件同步更新、长任务取消和资源限制的条目，应优先进入 Alpha 已知风险、迁移提醒和恢复说明复核队列。</li></ul>',102)])])}const g=a(d,[["render",r]]);export{u as __pageData,g as default};
